// ResolvedClientCapabilities is a version of ClientCapabilities where all nested
// fields are values (not pointers), making it easier to access deeply nested capabilities.
// Use ClientCapabilities::resolve (Go: (*ClientCapabilities).Resolve()) to convert from ClientCapabilities.
//
// Defines the capabilities provided by the client.
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash)]
pub struct ResolvedClientCapabilities {
    // Workspace specific client capabilities.
    pub workspace: ResolvedWorkspaceClientCapabilities,

    // Text document specific client capabilities.
    pub text_document: ResolvedTextDocumentClientCapabilities,

    // Window specific client capabilities.
    pub window: ResolvedWindowClientCapabilities,

    // General client capabilities.
    //
    // Since: 3.16.0
    pub general: ResolvedGeneralClientCapabilities,

    // Experimental client capabilities.
    pub experimental: ResolvedExperimentalClientCapabilities,

    // Whether the client supports Visual Studio extensions.
    pub vs_supports_visual_studio_extensions: bool,

    // The snippet version supported by the client.
    pub vs_supported_snippet_version: i32,

    // Whether the client supports not including text in textDocument/didOpen notifications.
    pub vs_supports_not_including_text_in_text_document_did_open: bool,

    // Whether the client supports icon extensions.
    pub vs_supports_icon_extensions: bool,

    // Whether the client supports diagnostic requests.
    pub vs_supports_diagnostic_requests: bool,
}

impl ClientCapabilities {
    // Go: (v *ClientCapabilities) Resolve
    pub fn resolve(v: Option<&ClientCapabilities>) -> ResolvedClientCapabilities {
        let Some(v) = v else {
            return ResolvedClientCapabilities::default();
        };
        ResolvedClientCapabilities {
            workspace: WorkspaceClientCapabilities::resolve(v.workspace.as_ref()),
            text_document: TextDocumentClientCapabilities::resolve(v.text_document.as_ref()),
            window: WindowClientCapabilities::resolve(v.window.as_ref()),
            general: GeneralClientCapabilities::resolve(v.general.as_ref()),
            experimental: ExperimentalClientCapabilities::resolve(v.experimental.as_ref()),
            vs_supports_visual_studio_extensions: deref_or(&v.vs_supports_visual_studio_extensions),
            vs_supported_snippet_version: deref_or(&v.vs_supported_snippet_version),
            vs_supports_not_including_text_in_text_document_did_open: deref_or(
                &v.vs_supports_not_including_text_in_text_document_did_open,
            ),
            vs_supports_icon_extensions: deref_or(&v.vs_supports_icon_extensions),
            vs_supports_diagnostic_requests: deref_or(&v.vs_supports_diagnostic_requests),
        }
    }
}



impl IsZero for ResolvedClientCapabilities {
    // PORT: Go reflect.Value.IsZero (omitzero).
    fn is_zero(&self) -> bool {
        self.workspace.is_zero()
            && self.text_document.is_zero()
            && self.window.is_zero()
            && self.general.is_zero()
            && self.experimental.is_zero()
            && !self.vs_supports_visual_studio_extensions
            && self.vs_supported_snippet_version == 0
            && !self.vs_supports_not_including_text_in_text_document_did_open
            && !self.vs_supports_icon_extensions
            && !self.vs_supports_diagnostic_requests
    }
}
